use vstd::prelude::*;

verus! {
    /// Creates a row of numbers from 0 to n-1.
    /// 
    /// # Preconditions
    /// - `n` must be less than or equal to 255 to fit in a `u8`.
    /// 
    /// # Postconditions
    /// - The length of the returned vector is equal to `n`.
    /// - The elements of the vector are in the range [0, n-1].
    spec fn create_row(n: u8) -> Vec<u8>
        requires
            n <= 255,
        ensures
            result.len() == n as usize,
            forall |i: usize| (i < result.len() ==> result[i] < n),
    {
        let mut v: Vec<u8> = Vec::new();
        for i in 0..n {
            v.push(i);
        }
        v
    }

    /// Creates a vector containing a single row of numbers from 0 to n-1.
    /// 
    /// # Preconditions
    /// - `n` must be less than or equal to 255 to fit in a `u8`.
    /// 
    /// # Postconditions
    /// - The returned vector contains exactly one element, which is the result of `create_row(n)`.
    spec fn indices(n: u8) -> Vec<Vec<u8>>
        requires
            n <= 255,
        ensures
            result.len() == 1,
            result[0] == create_row(n),
    {
        vec![create_row(n)]
    }

    fn main() {
        // Example usage
        let n = 5;
        let row = create_row(n);
        let grid = indices(n);
        
        println!("{:?}", row); // Output: [0, 1, 2, 3, 4]
        println!("{:?}", grid); // Output: [[0, 1, 2, 3, 4]]
    }
}